/* Native span observations only; every policy/numeric decision is in Coax. */
#include "deepseek-prefill-memory.h"
#include "spans.h"
typedef struct {const void *data;int64_t count;size_t width;} DpSpan;
#define DP_SPAN(x) (DpSpan){(x).data,(x).count,sizeof(*(x).data)}
static _Bool dp_alias(DpSpan *w,size_t nw,DpSpan *r,size_t nr){for(size_t i=0;i<nw;i++){for(size_t j=0;j<i;j++)if(psionic_spans_overlap(w[i].data,w[i].count,w[i].width,w[j].data,w[j].count,w[j].width))return 1;for(size_t j=0;j<nr;j++)if(psionic_spans_overlap(w[i].data,w[i].count,w[i].width,r[j].data,r[j].count,r[j].width))return 1;}return 0;}
static _Bool dp_matrix_alias(DpSpan *w,size_t n,coax_t_DeMatrix m){DpSpan r[]={DP_SPAN(m.data),DP_SPAN(m.scales)};return dp_alias(w,n,r,2);}
coax_t_DpResult psionic_dp_project(coax_t_DeMatrix m,int64_t n,coax_v_f32 x,coax_v_f32 out,coax_v_f64 q,coax_v_f32 stage,coax_v_u8 flags){DpSpan w[]={DP_SPAN(out),DP_SPAN(q),DP_SPAN(stage),DP_SPAN(flags)},r[]={DP_SPAN(x)};return dp_project(m,n,x,out,q,stage,flags,dp_alias(w,4,r,1)||dp_matrix_alias(w,4,m));}
coax_t_DpResult psionic_dp_expert(coax_t_DeExpert e,int64_t n,coax_v_f32 x,coax_v_f32 routes,float limit,coax_v_f32 out,coax_t_DpWork work){DpSpan w[]={DP_SPAN(out),DP_SPAN(work.floats),DP_SPAN(work.wide),DP_SPAN(work.flags)},r[]={DP_SPAN(x),DP_SPAN(routes)};return dp_expert(e,n,x,routes,limit,out,work,dp_alias(w,4,r,2)||dp_matrix_alias(w,4,e.gate)||dp_matrix_alias(w,4,e.up)||dp_matrix_alias(w,4,e.down));}
coax_t_DpResult psionic_dp_groups(int64_t e,int64_t n,int64_t k,coax_v_s64 ids,coax_v_f32 weights,coax_v_s64 order,coax_v_s64 offsets,coax_v_s64 keys,coax_v_s64 so,coax_v_s64 sf,coax_v_s64 sk){DpSpan w[]={DP_SPAN(order),DP_SPAN(offsets),DP_SPAN(keys),DP_SPAN(so),DP_SPAN(sf),DP_SPAN(sk)},r[]={DP_SPAN(ids),DP_SPAN(weights)};return dp_groups(e,n,k,ids,weights,order,offsets,keys,so,sf,sk,dp_alias(w,6,r,2));}
coax_t_DpResult psionic_dp_gather(int64_t e,int64_t n,int64_t k,int64_t d,int64_t id,coax_v_s64 ids,coax_v_f32 weights,coax_v_s64 order,coax_v_s64 offsets,coax_v_f32 x,coax_v_f32 out,coax_v_f32 routes){DpSpan w[]={DP_SPAN(out),DP_SPAN(routes)},r[]={DP_SPAN(ids),DP_SPAN(weights),DP_SPAN(order),DP_SPAN(offsets),DP_SPAN(x)};return dp_gather(e,n,k,d,id,ids,weights,order,offsets,x,out,routes,dp_alias(w,2,r,5));}
coax_t_DpResult psionic_dp_scatter(int64_t e,int64_t n,int64_t k,int64_t d,int64_t id,coax_v_s64 ids,coax_v_s64 order,coax_v_s64 offsets,coax_v_f32 x,coax_v_f32 out){DpSpan w[]={DP_SPAN(out)},r[]={DP_SPAN(ids),DP_SPAN(order),DP_SPAN(offsets),DP_SPAN(x)};return dp_scatter(e,n,k,d,id,ids,order,offsets,x,out,dp_alias(w,1,r,4));}
coax_t_DpResult psionic_dp_combine(int64_t e,int64_t n,int64_t k,int64_t d,coax_v_s64 ids,coax_v_f32 weights,coax_v_u8 receipts,_Bool shared_ready,coax_v_f32 contribution,coax_v_f32 shared,coax_v_f32 out,coax_v_f32 stage){DpSpan w[]={DP_SPAN(out),DP_SPAN(stage)},r[]={DP_SPAN(ids),DP_SPAN(weights),DP_SPAN(receipts),DP_SPAN(contribution),DP_SPAN(shared)};return dp_combine(e,n,k,d,ids,weights,receipts,shared_ready,contribution,shared,out,stage,dp_alias(w,2,r,5));}
